index 362cae7a3714053e3a1fb3e55f73e28f0ee623ef..e69a217d63735a32ea299eab6c41f4f0e64a16d2 100644
--- a/src/helpers/http.ts
+++ b/src/helpers/http.ts
@@ -1,6 +1,10 @@
-import axios from "axios";
+import { z } from "zod";

-export async function fetchJson<T>(url: string): Promise<T> {
-  const response = await axios.get<T>(url);
-  return response.data;
+export async function fetchJson<T>(url: string, schema: z.ZodType<T>): Promise<T> {
+  const response = await fetch(url);
+  if (!response.ok) {
+    throw new Error(`HTTP ${response.status} for ${url}`);
+  }
+  const data: unknown = await response.json();
+  return schema.parse(data);
 }

